alter table public.profiles add column if not exists community_opt_in boolean not null default false;
alter table public.profiles add column if not exists avatar_url text;
create unique index if not exists profiles_public_display_name_unique on public.profiles(lower(display_name)) where community_opt_in and display_name is not null;
create table if not exists public.community_goals(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,description text not null,target_count bigint not null check(target_count>0),starts_at date not null,ends_at date,active boolean not null default true,created_at timestamptz not null default now());
alter table public.community_goals enable row level security;
create policy community_goals_authenticated_read on public.community_goals for select to authenticated using(true);
insert into public.community_goals(slug,title,description,target_count,starts_at,ends_at,active) values('cleanup-together','Gemeinsam sauberer','Jeder synchronisierte Fund zählt für unser gemeinsames Ziel.',10000,date_trunc('year',current_date)::date,null,true) on conflict(slug) do nothing;
create or replace function public.community_goal_progress(p_goal_id uuid) returns table(goal_id uuid,title text,target_count bigint,current_count bigint,starts_at date,ends_at date) language sql security definer set search_path=public as $$ select goal.id,goal.title,goal.target_count,coalesce(sum(collection.count),0)::bigint,goal.starts_at,goal.ends_at from public.community_goals goal left join public.daily_collections collection on collection.deleted_at is null and collection.date_key>=goal.starts_at and (goal.ends_at is null or collection.date_key<=goal.ends_at) where auth.uid() is not null and goal.id=p_goal_id and goal.active group by goal.id,goal.title,goal.target_count,goal.starts_at,goal.ends_at; $$;
create or replace function public.weekly_leaderboard(p_limit integer default 25) returns table(rank bigint,display_name text,avatar_url text,total_count bigint) language sql security definer set search_path=public as $$ select row_number() over(order by sum(collection.count) desc,profile.display_name asc),profile.display_name,profile.avatar_url,sum(collection.count)::bigint from public.profiles profile join public.daily_collections collection on collection.user_id=profile.id and collection.deleted_at is null where auth.uid() is not null and profile.community_opt_in and profile.display_name is not null and collection.date_key>=date_trunc('week',current_date)::date group by profile.id,profile.display_name,profile.avatar_url order by sum(collection.count) desc,profile.display_name asc limit least(greatest(coalesce(p_limit,25),1),50); $$;
revoke all on function public.community_goal_progress(uuid) from public;
revoke all on function public.weekly_leaderboard(integer) from public;
grant execute on function public.community_goal_progress(uuid) to authenticated;
grant execute on function public.weekly_leaderboard(integer) to authenticated;